// What list_threads and change_threads do (./thread-tools.ts; docs/specs/015-api/mcp-server.md "Comment threads"),
// over a canvas product's comment endpoints (`/<collection>/:id/comments`, `/<collection>/:id/tabs/:tab/comments...`).
// A thread lives on an element, so it is named by the element's ref: one with a thread is found in the listing,
// across every tab; one with none (a start) on the tab named, else the first. A comment is named by its id or a
// prefix. The api stamps every comment an agent writes Generated by AI and refuses an agent's edit or delete of any
// comment it did not write; the run refuses it first, in words.

import { ApiError, type ApiClient } from '@liveworkspace/api-client';
import type {
  CommentListStatus,
  DocumentCommentThread,
  DocumentCommentsResponse,
} from '@liveworkspace/api-schema/comment-threads';
import { computeRefs, resolveRef } from '@liveworkspace/element-model/element-refs';
import { wordOf, type AgentProduct } from '../product';

export type ThreadChange =
  | { op: 'start'; ref: string; tabId?: string; text: string }
  | { op: 'reply'; ref: string; tabId?: string; text: string }
  | { op: 'resolve'; ref: string; tabId?: string }
  | { op: 'reopen'; ref: string; tabId?: string }
  | { op: 'edit'; ref: string; tabId?: string; comment: string; text: string }
  | { op: 'delete'; ref: string; tabId?: string; comment: string };

export type ListedThreadComment = {
  id: string;
  author: string;
  at: string;
  text: string;
  ai?: true;
  edited?: true;
  reactions?: { emoji: string; name: string; count: number; by: string[] }[];
};

export type ListedCanvasThread = {
  tabId: string;
  tabName: string;
  ref: string;
  label: string | null;
  state: 'open' | 'resolved';
  comments: ListedThreadComment[];
};

type Thread = DocumentCommentThread;
type Tab = { id: string; name: string };

// Words for the comment endpoints' own refusals (Agent presence "Comments"); the rest are the product's refusalOf.
const THREAD_REFUSALS: Readonly<Record<string, string>> = {
  not_ai_comment:
    'The api refused it: that comment was written by a person. An agent edits and deletes only its own comments (those marked ai).',
  thread_full:
    'The api refused it: that thread holds the most comments it can (500). Comment on another element.',
  tab_busy: 'The api refused it: the tab kept changing. Make the same call again.',
};

// A comment named by a prefix needs at least this much of its id.
export const COMMENT_PREFIX_MIN = 4;

// A change the run refused before any call, or the api after one, in words.
export class ThreadStop extends Error {
  readonly code: string;
  constructor(code: string, message: string) {
    super(message);
    this.code = code;
  }
}

export function listedThread(t: Thread): ListedCanvasThread {
  return {
    tabId: t.tabId,
    tabName: t.tabName,
    ref: t.ref,
    label: t.label,
    state: t.resolved ? 'resolved' : 'open',
    comments: t.comments.map((c) => ({
      id: c.id,
      author: c.authorName,
      at: new Date(c.createdAt).toISOString(),
      text: c.text,
      ...(c.ai ? { ai: true as const } : {}),
      ...(c.editedAt ? { edited: true as const } : {}),
      ...(c.reactions?.length ? { reactions: c.reactions } : {}),
    })),
  };
}

export function createThreadRun(product: AgentProduct) {
  const { noun, collection } = product;
  const word = wordOf(product);
  const filePath = (id: string) => `/${collection}/${encodeURIComponent(id)}`;
  const commentsPath = (id: string, tabId: string) =>
    `${filePath(id)}/tabs/${encodeURIComponent(tabId)}/comments`;

  const readThreads = async (api: ApiClient, id: string, status: CommentListStatus) =>
    (await api.json<Partial<DocumentCommentsResponse>>(`${filePath(id)}/comments?status=${status}`))
      .threads ?? [];

  const readTabs = async (api: ApiClient, id: string): Promise<Tab[]> => {
    const body = await api.json<Record<string, { tabs?: Tab[] } | undefined>>(filePath(id));
    return body[noun]?.tabs ?? [];
  };

  // The tab `ref` names among `tabs`, by id or name (case aside), or the first when none is named.
  function tabOf(tabs: readonly Tab[], ref: string | undefined): Tab {
    if (ref === undefined) {
      const first = tabs[0];
      if (!first) throw new ThreadStop('no_tabs', `That ${word} has no tabs.`);
      return first;
    }
    const want = ref.trim().toLowerCase();
    const found =
      tabs.find((t) => t.id === ref.trim()) ?? tabs.find((t) => t.name.toLowerCase() === want);
    if (!found)
      throw new ThreadStop(
        'tab_unknown',
        `No tab "${ref}". The tabs: ${tabs.map((t) => `${t.id} "${t.name}"`).join('; ')}.`,
      );
    return found;
  }

  /** The threads list_threads answers: the status asked for, every tab or the one named. */
  async function listThreads(
    api: ApiClient,
    id: string,
    status: CommentListStatus,
    tab?: string,
  ): Promise<ListedCanvasThread[]> {
    const threads = await readThreads(api, id, status);
    if (tab === undefined) return threads.map(listedThread);
    const only = tabOf(await readTabs(api, id), tab);
    return threads.filter((t) => t.tabId === only.id).map(listedThread);
  }

  // The thread on the element `ref` names: its ref or an element id prefix, on the tab named or any tab.
  function threadOn(threads: readonly Thread[], ref: string, tabId: string | undefined): Thread {
    const want = ref.trim();
    const here = tabId === undefined ? threads : threads.filter((t) => t.tabId === tabId);
    const exact = here.filter((t) => t.ref === want || t.elementId === want);
    const matches = exact.length ? exact : here.filter((t) => t.elementId.startsWith(want));
    if (matches.length === 1) return matches[0]!;
    if (matches.length > 1)
      throw new ThreadStop(
        'ref_ambiguous',
        `${ref} names more than one thread: ${matches.map((t) => `${t.ref} on "${t.tabName}"`).join('; ')}. Give its tabId.`,
      );
    throw new ThreadStop(
      'no_thread',
      `No thread on ${ref}. Threads: ${
        here.length ? here.map((t) => `${t.ref} on "${t.tabName}"`).join('; ') : 'none'
      }. Start one with start.`,
    );
  }

  // The element `ref` names on a tab, over every element of it, as the views name them.
  async function elementOn(api: ApiClient, id: string, tab: Tab, ref: string): Promise<string> {
    const { tab: body } = await api.json<{ tab: { elements: { id: string }[] } }>(
      `${filePath(id)}/tabs/${encodeURIComponent(tab.id)}`,
    );
    const found = resolveRef(ref, computeRefs(body.elements.map((el) => el.id)));
    if (found.kind === 'found') return found.id;
    throw new ThreadStop(
      found.kind === 'ambiguous' ? 'ref_ambiguous' : 'ref_not_found',
      found.kind === 'ambiguous'
        ? `${ref} names ${found.candidates.length} elements on tab "${tab.name}": give more of it.`
        : `No element ${ref} on tab "${tab.name}".${
            found.nearest.length ? ` Nearest: ${found.nearest.join(', ')}.` : ''
          }`,
    );
  }

  // The comment an agent may change in `thread`: named by id or prefix, and one an agent wrote.
  function ownComment(thread: Thread, ref: string): Thread['comments'][number] {
    const want = ref.trim();
    const exact = thread.comments.find((c) => c.id === want);
    const matches = exact
      ? [exact]
      : want.length >= COMMENT_PREFIX_MIN
        ? thread.comments.filter((c) => c.id.startsWith(want))
        : [];
    if (matches.length !== 1)
      throw new ThreadStop(
        matches.length ? 'comment_ambiguous' : 'comment_unknown',
        `${matches.length ? `"${ref}" names more than one comment` : `No comment "${ref}"`} on ${thread.ref}: ${thread.comments
          .map((c) => `${c.id} by ${c.authorName}`)
          .join('; ')}`,
      );
    const comment = matches[0]!;
    if (!comment.ai)
      throw new ThreadStop(
        'not_ai_comment',
        `Comment ${comment.id} by ${comment.authorName} was written by a person: an agent edits and deletes only its own comments (those marked ai).`,
      );
    return comment;
  }

  async function send(api: ApiClient, path: string, method: string, body?: unknown) {
    const res = await api.fetch(path, {
      method,
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
    if (!res.ok) throw new ApiError(res.status, await res.text());
  }

  /** Applies `changes` in order, each against the threads as the ones before it left them. The first refusal stops
   *  the rest and says what was applied before it. */
  async function applyThreadChanges(
    api: ApiClient,
    id: string,
    changes: readonly ThreadChange[],
    refusalOf: (err: unknown) => { code: string; message: string } | null,
  ): Promise<{ applied: string[]; refusal?: { code: string; message: string } }> {
    const applied: string[] = [];
    let tabs: Tab[] | null = null;
    let threads: Thread[] | null = null;
    const current = async () => (threads ??= await readThreads(api, id, 'all'));
    const tabNamed = async (ref: string | undefined) =>
      ref === undefined ? undefined : tabOf((tabs ??= await readTabs(api, id)), ref).id;
    for (const change of changes) {
      try {
        const tabId = await tabNamed(change.tabId);
        if (change.op === 'start') {
          const tab = tabOf((tabs ??= await readTabs(api, id)), change.tabId);
          const elementId = await elementOn(api, id, tab, change.ref);
          await send(api, commentsPath(id, tab.id), 'POST', { elementId, text: change.text });
          applied.push(`+ comment on ${change.ref}`);
        } else {
          const thread = threadOn(await current(), change.ref, tabId);
          const at = commentsPath(id, thread.tabId);
          const last = encodeURIComponent(thread.comments.at(-1)!.id);
          if (change.op === 'reply') {
            await send(api, `${at}/${last}/reply`, 'POST', { text: change.text });
            applied.push(`+ reply on ${thread.ref}`);
          } else if (change.op === 'resolve' || change.op === 'reopen') {
            await send(api, `${at}/${last}/${change.op}`, 'POST');
            applied.push(`~ thread ${thread.ref} ${change.op === 'resolve' ? 'resolved' : 'open'}`);
          } else {
            const comment = ownComment(thread, change.comment);
            const path = `${at}/${encodeURIComponent(comment.id)}`;
            if (change.op === 'edit') {
              await send(api, path, 'PUT', { text: change.text });
              applied.push(`~ comment ${comment.id} on ${thread.ref}`);
            } else {
              await send(api, path, 'DELETE');
              applied.push(`- comment ${comment.id} from ${thread.ref}`);
            }
          }
        }
        // The next change sees this one.
        threads = null;
      } catch (err) {
        if (err instanceof ThreadStop)
          return { applied, refusal: { code: err.code, message: err.message } };
        const words = err instanceof ApiError && err.code ? THREAD_REFUSALS[err.code] : undefined;
        if (words) return { applied, refusal: { code: (err as ApiError).code!, message: words } };
        const refusal = refusalOf(err);
        if (!refusal) throw err;
        return { applied, refusal };
      }
    }
    return { applied };
  }

  return { listThreads, applyThreadChanges };
}

/** The error text a stopped change_threads answers: what was applied first, then why it stopped. */
export function threadStopText(applied: readonly string[], refusal: { message: string }): string {
  return applied.length
    ? `Applied before it stopped:\n${applied.join('\n')}\nThen: ${refusal.message}`
    : refusal.message;
}
